{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C61"],
      "claim": "Posaconazole, a large lipophilic triazole-containing drug with high transfer to the query, had absolute oral bioavailability 0.54–0.75 in patients, supporting a high F prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Atazanavir, a large poorly soluble HIV drug, had 68% (57–80%) absolute oral bioavailability in humans, supporting high F for a large lipophilic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Perindopril, a carboxylic acid-containing drug, had 66% absolute oral bioavailability in humans, supporting high F despite an ionizable acid group.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Ursodeoxycholic acid, a steroid carboxylic acid structurally closest to the query's pentacyclic acid scaffold, had 50% systemic availability in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Cilomilast, a lipophilic carboxylic acid, had 96% absolute oral bioavailability in healthy volunteers, showing that carboxylic acid and lipophilicity do not preclude high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "BI 425809 had 71.6% absolute oral bioavailability in humans, supporting high F for a lipophilic oral drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Pentazocine had 18% absolute oral bioavailability in healthy subjects, a direct low-F measurement contradictory to a high prediction, though its smaller scaffold and lower transfer reduce weight.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C53"],
      "claim": "Perindoprilat, the diacid metabolite, had 19% ± 7% bioavailability after oral perindopril, a direct low-F measurement for a carboxylic acid-containing molecule, contradictory but less transferable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C64"],
      "claim": "Posaconazole suspension had 16% (8–27%) absolute bioavailability in pediatric patients, showing that formulation and population can drop below 20% even for a high-F drug; this is contradictory but context-specific.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "High: the preponderance of high-transfer experimental analogues (posaconazole, atazanavir, perindopril, UDCA, cilomilast) show F ≥ 50%, and the closest steroid-acid analogue UDCA is 50% bioavailable; low-F analogues are less transferable and do not outweigh this.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the query molecule.",
    "Formulation and food effects are unknown; posaconazole F ranges from 16% to >90% depending on formulation and population.",
    "First-pass metabolism, efflux transport, and solubility-limited absorption of the query are not directly characterized.",
    "No exact structural analogue with the same triterpenoid-azole-amine scaffold is present."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

